// Installed before original theme/sync/scripts. Never touches browser Storage.
(()=>{const values=new Map([['med_exam_active_tab','kingdom'],['med_exam_theme','light']]);window.reviewStorage=Object.freeze({getItem:k=>values.get(String(k))??null,setItem:(k,v)=>values.set(String(k),String(v)),removeItem:k=>values.delete(String(k)),clear:()=>values.clear(),key:i=>[...values.keys()][i]??null,get length(){return values.size;}});Object.defineProperty(window,'localStorage',{configurable:true,value:window.reviewStorage});window.workspaceLocalOnly=false;window.i3FixtureOnly=true;
document.addEventListener('click',event=>{const a=event.target.closest('a[href]');if(a&&/^https?:/.test(a.getAttribute('href'))&&new URL(a.href).origin!==location.origin)event.preventDefault();},true);})();
